				continue
			}

			if existing, ok := candidateMap[r.AdvertisedName]; ok {
				// Keep the higher score
				if r.Score > existing.Score {
					existing.Score = r.Score
					existing.Reason = r.MatchReason
				}
			} else {
				candidateMap[r.AdvertisedName] = &ToolAdvertisement{
